// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BundleAnalyticsEvents) predicate.BundleAnalyticsEvents {
	return predicate.BundleAnalyticsEvents(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BundleAnalyticsEvents) predicate.BundleAnalyticsEvents {
	return predicate.BundleAnalyticsEvents(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BundleAnalyticsEvents) predicate.BundleAnalyticsEvents {
	return predicate.BundleAnalyticsEvents(sql.NotPredicates(p))
}
